/* Prices, departure dates and remaining seats are illustrative for this fictional travel concept. */
globalThis.TRIP_CATALOG=[{name:'Goa',price:8999,days:4,nights:3,departure:'2026-11-28',closing:'2026-11-23',seats:16},{name:'Himachal',price:12999,days:5,nights:4,departure:'2026-11-11',closing:'2026-11-10',seats:3},{name:'Meghalaya',price:18999,days:6,nights:5,departure:'2026-12-05',closing:'2026-12-01',seats:14},{name:'Rajasthan',price:9999,days:4,nights:3,departure:'2026-11-27',closing:'2026-11-22',seats:12},{name:'North East',price:22999,days:7,nights:6,departure:'2026-12-12',closing:'2026-12-07',seats:18}];
globalThis.daysUntil=function(date,now=new Date()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now).map(x=>[x.type,x.value]));const today=Date.UTC(+p.year,+p.month-1,+p.day);const [y,m,d]=date.split('-').map(Number);return Math.round((Date.UTC(y,m-1,d)-today)/86400000);};
globalThis.tripPrice=function(name){return '₹'+TRIP_CATALOG.find(t=>t.name===name).price.toLocaleString('en-IN');};
globalThis.nextTrip=function(now=new Date()){return TRIP_CATALOG.filter(t=>t.departure&&daysUntil(t.departure,now)>=0).sort((a,b)=>a.departure.localeCompare(b.departure))[0]||null;};
globalThis.tripInfo=function(name){const t=TRIP_CATALOG.find(x=>x.name===name);const duration=`${t.days} days · ${t.nights} nights`;if(daysUntil(t.departure)<0)return `<div class="trip-facts"><span>${duration}</span><span>Next dates coming soon</span></div>`;const date=new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(t.departure+'T00:00:00Z'));return `<div class="trip-facts"><span>${duration}</span><span>Next: ${date}</span><span class="trip-seats">${t.seats} seats left</span></div>`;};

globalThis.discountTotal=function(price,percent){return price-Math.round(price*percent/100);};
globalThis.tripOffer=function(name,now=new Date()){const trip=TRIP_CATALOG.find(t=>t.name===name);if(!trip||!trip.closing||trip.seats<=0)return null;const departureRemaining=daysUntil(trip.departure,now);const remaining=daysUntil(trip.closing,now);if(remaining<0||departureRemaining<0)return null;if(remaining<5&&departureRemaining<5&&trip.seats<5)return {code:'LASTCALL',percent:5,label:'Closing soon',closing:trip.closing,remaining};if(remaining>=14&&departureRemaining>0&&trip.seats>=10)return {code:'EARLYBIRD',percent:10,label:'Early bird',closing:trip.closing,remaining};return null;};
